// Required header constants (system dependent)
#define ICACHE 1    // Instruction Cache
#define DCACHE 2    // Data Cache
#define BCACHE 3    // Both

void* addr = allocated_memory;
int nbytes = 512;
int result;

// Prototype: int cacheflush(void* addr, int nbytes, int cache);

// Example 1: Flush Data Cache
result = cacheflush(addr, nbytes, DCACHE);

// Example 2: Flush Instruction Cache (e.g., after JIT compilation)
result = cacheflush(addr, nbytes, ICACHE);

// Example 3: Flush Both Caches
result = cacheflush(addr, nbytes, BCACHE);
